        case "GameStatsMode":return new[]{"CAMPAIGN_GAME","LAN_GAME","ONLINE_CLAN_1V1_GAME","ONLINE_CLAN_2V2_GAME","ONLINE_RANKED_1V1_GAME","ONLINE_RANKED_2V2_GAME","ONLINE_UNRANKED_GAME","SKIRMISH_GAME"};
        case "AIBuildHeuristics":return new[]{"BEST_UNIT_ACTUAL","BEST_UNIT_EXPECTED","BEST_UNIT_WEIGHTED","BUILD_TEST","CONSTANT","FACTORY","FEWEST_UNIT","HARVESTER","NEEDED_UNIT","POWER","RANDOM_UNIT","REFINERY","TECH","UNIQUE","UPGRADE","UPGRADE_TECH","UPGRADE_TEST","WORST_UNIT"};
        default:throw new Exception("Unknown enum fixture");}}
    static IEnumerable<string> Values(Field f){
        if(f.Kind=="Bool"){foreach(string x in Bools)yield return x;yield break;}
        if(f.Kind=="Reference"){foreach(string x in Refs)yield return x;yield break;}
        if(f.Kind=="String"||f.Kind=="Hash"){foreach(string x in Strings)yield return x;yield break;}
        if(f.Kind=="Enum"){foreach(string x in EnumNames(f.Enum))yield return x;foreach(string x in new[]{"","unknown","0","-1","ALL",EnumNames(f.Enum)[0].ToLowerInvariant()," "+EnumNames(f.Enum)[0]})yield return x;yield break;}
        if(f.Kind=="Tokens"){foreach(string x in new[]{""," ","1 2 3","0x10 077 -1","1,2,3","garbage 4294967296","1\t2\r\n3","1  1  0"})yield return x;yield break;}
        if(f.Kind=="Model"){foreach(string x in ModelNames)yield return x;foreach(string x in new[]{"","ALL","all","UNKNOWN","INVALID","ALL -ALL","ATTACKING MOVING -MOVING","-UNKNOWN -UNKNOWN"})yield return x;yield break;}
        foreach(string x in Numbers)yield return x;
        if(f.Kind=="Time")foreach(string x in new[]{"1s","2500ms","2s ms","2ms s","-1s","1.5s"})yield return x;
        if(f.Kind=="Angle")foreach(string x in new[]{"90d","-180d","2r","359d"})yield return x;
    }
    static void Matrix(IAssetBuilderPlugin original,TargetPlatform p){
        original.Initialize(null,p);
        {AssetBuffer b=Test(original,p,"AIData/defaults",Root("AIData","",""));Assert(b.InstanceData.Length==220,"independent default root size");}
        {AssetBuffer b=Test(original,p,"UnitAISettings/defaults",Root("UnitAISettings","",""));Assert(b.InstanceData.Length==448,"independent default root size");}
        {AssetBuffer b=Test(original,p,"PlayerTemplate/defaults",Root("PlayerTemplate","",""));Assert(b.InstanceData.Length==188,"independent default root size");}
        {AssetBuffer b=Test(original,p,"MultiplayerSettings/defaults",Root("MultiplayerSettings","",""));Assert(b.InstanceData.Length==44,"independent default root size");}
        {AssetBuffer b=Test(original,p,"AIBuildStateDefinition/defaults",Root("AIBuildStateDefinition","",""));Assert(b.InstanceData.Length==20,"independent default root size");}
        {AssetBuffer b=Test(original,p,"AIStrategicStateName/defaults",Root("AIStrategicStateName","",""));Assert(b.InstanceData.Length==16,"independent default root size");}
        {AssetBuffer b=Test(original,p,"MultiplayerColor/defaults",Root("MultiplayerColor","",""));Assert(b.InstanceData.Length==28,"independent default root size");}
        {AssetBuffer b=Test(original,p,"AIPersonalityToAchievementEventMapping/defaults",Root("AIPersonalityToAchievementEventMapping","",""));Assert(b.InstanceData.Length==12,"independent default root size");}
        foreach(string type in new[]{"AIData","UnitAISettings","PlayerTemplate","TechProductionBonusInfo","PlayerTemplateAIBeaconSettings","MoneyTransaction","GameStatsModeData","AIBuildEntry","AIStrategicStateName","AIPersonalityToAchievementEventMapping"}){
            foreach(Field f in Fields(type))foreach(string value in Values(f))Test(original,p,type+"/"+f.Name+"/"+value,Context(type,A(f.Name,value),""));
            string all="";foreach(Field f in Fields(type)){string value=f.Kind=="Bool"?"true":f.Kind=="Reference"?"Ref\\7":f.Kind=="String"||f.Kind=="Hash"?"abcd":f.Kind=="Enum"?EnumNames(f.Enum)[0]:f.Kind=="Model"?"ATTACKING MOVING":f.Kind=="Tokens"?"1 2 3":"17.125";all+=A(f.Name,value);}Test(original,p,type+"/all-fields",Context(type,all,""));
            Reject(Context(type,"Bogus='1'",""),p);Reject(Context(type,"xmlns:q='urn:foreign' q:TypeId='1'",""),p);Reject(Context(type,"","<Unknown/>"),p);
        }
        ChildMatrix(original,p);FixedLayouts(original,p);AiBuildMatrix(original,p);MetadataMatrix(original,p);AdditionalMatrix(original,p);
    }
